function topFrame(node){ let n=node; while(n.parent && n.parent.type!=='PAGE') n=n.parent; return n; }
function link(fromNode, toFrame){
  if(!fromNode || !toFrame) return 'missing';
  if(topFrame(fromNode).id === toFrame.id) return 'same-frame';
  fromNode.reactions = [{
    trigger: { type: 'ON_CLICK' },
    actions: [{ type: 'NODE', destinationId: toFrame.id, navigation: 'NAVIGATE', transition: null, preserveScrollPosition: false }]
  }];
  return 'ok';
}
